// Shape of the library manifests (/token-library.json, /maps-library.json),
// generated by vite-plugins/token-library.ts from folders under public/.

export interface LibraryItem {
    /** Display name (file name without extension) */
    name: string
    /** URL the full image is served from, relative to the app base */
    url: string
    /** Small preview image URL, when the library generates thumbnails */
    thumb?: string
}

export interface LibraryFolder {
    /** Folder name ("" for the library root) */
    name: string
    /** Path segments from the library root, e.g. ["Fey", "Nymphs"] */
    path: string[]
    folders: LibraryFolder[]
    tokens: LibraryItem[]
    /** Total number of items in this folder and all subfolders */
    totalTokens: number
}

/** @deprecated use LibraryItem */
export type TokenLibraryToken = LibraryItem
/** @deprecated use LibraryFolder */
export type TokenLibraryFolder = LibraryFolder
